actions.script:
// Change 2: Walk iteratively so a deep site map does not consume nested script stacks.
// getMenuItems still authorizes every entry, including hidden entries in Show All.
const initialPath = typeof currentScreenPath === 'undefined' ? '' : currentScreenPath
const pending = [{kind: 'branch', path: initialPath, ancestors: []}]
siteMapEvents = []
while (pending.length) {
    const event = pending.pop()
    if (event.kind !== 'branch') { siteMapEvents.push(event); continue }
    siteMapEvents.push({kind: 'open'})
    pending.push({kind: 'close'})
    const items = sri.getMenuItems(event.path || '/', showAll == 'true')
    for (let i = items.length - 1; i >= 0; i--) {
        const item = items[i]
        if (event.ancestors.includes(item.location) || (showAll != 'true' && item.hasRequiredParameters)) continue
        const path = event.path + '/' + item.name
        pending.push({kind: 'branch', path, ancestors: event.ancestors.concat([item.location])})
        pending.push({kind: 'item', path, title: item.title, link: !item.hasRequiredParameters && !item.disabled})
    }
}
